<?php
if (!isset($scope,$directory,$term)) { http_response_code(404); exit; }
$filters = $directory['filters']; $pagination = $directory['pagination']; $options = $directory['options'];
$studentUrl = static function (array $changes = []) use ($pageUrl,$filters): string {
    $params = $filters; unset($params['term'],$params['ay_id'],$params['semester']);
    return $pageUrl('students.php',array_merge($params,['directory_term'=>$filters['term']],$changes));
};
?>
