    <div><label for="student-directory-term">Academic year / semester</label><select class="form-select" id="student-directory-term" name="directory_term"><option value="all"<?= $filters['term']==='all' ? ' selected' : '' ?>>All academic terms</option><?php foreach($years as $year): ?><option value="year:<?= (int)$year['ay_id'] ?>"<?= $filters['term']==='year:'.$year['ay_id'] ? ' selected' : '' ?>><?= synk_management_h($year['ay']) ?> · All semesters</option><?php for($semester=1;$semester<=3;$semester++): $key=$year['ay_id'].':'.$semester; ?><option value="<?= $key ?>"<?= $filters['term']===$key ? ' selected' : '' ?>><?= synk_management_h($year['ay'].' · '.synk_semester_label($semester)) ?></option><?php endfor; endforeach; ?></select></div>
