    <div><label for="student-section">Class section</label><select class="form-select" id="student-section" name="section_id"><option value="0">All class sections</option><?php foreach ($options['sections'] as $section): $visible=(!$filters['program_id'] || $section['program_id']===$filters['program_id']) && (!$filters['ay_id'] || $section['ay_id']===$filters['ay_id']) && (!$filters['semester'] || $section['semester']===$filters['semester']); ?><option value="<?= $section['section_id'] ?>" data-program="<?= $section['program_id'] ?>" data-term="<?= $section['term'] ?>"<?= $filters['section_id']===$section['section_id'] ? ' selected' : '' ?><?= !$visible ? ' hidden disabled' : '' ?>><?= synk_management_h($section['section_label']) ?></option><?php endforeach; ?></select></div>
    <div><label for="student-email-status">Email status</label><select class="form-select" id="student-email-status" name="email_status"><?php foreach(['all'=>'All emails','missing'=>'Missing email','present'=>'With email'] as $value=>$label): ?><option value="<?= $value ?>"<?= $filters['email_status']===$value ? ' selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div>
